-- Xmip Storage on MariaDB: the runtime database.
--
-- Generated by xmip-core-persist (storage::schema), the definition the
-- backend reads and writes by; do not edit. `cargo test --test database`
-- at the estate root fails when this file differs from what it writes.
-- What to run, in what order and why: README.md beside this file.
--
-- Run as root with the mariadb client.

-- Its text utf8mb4, compared byte for byte, as Xmip compares it.
CREATE DATABASE `xmip_runtime` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
GRANT ALL PRIVILEGES ON `xmip_runtime`.* TO xmip_owner;
